-- 1. Crear extensiones necesarias para UUIDs y funciones criptográficas
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- Eliminar tablas previas si existen (en orden inverso de dependencias)
DROP TABLE IF EXISTS public."DOCTOR_ESPECIALIDAD" CASCADE;
DROP TABLE IF EXISTS public."SUSPENSION" CASCADE;
DROP TABLE IF EXISTS public."CONSULTA" CASCADE;
DROP TABLE IF EXISTS public."PACIENTE" CASCADE;
DROP TABLE IF EXISTS public."USUARIO" CASCADE;
DROP TABLE IF EXISTS public."DOCTOR" CASCADE;
DROP TABLE IF EXISTS public."ESPECIALIDAD" CASCADE;


-- -----------------------------------------------------
-- Tabla: ESPECIALIDAD
-- -----------------------------------------------------
CREATE TABLE public."ESPECIALIDAD" (
  "id_especialidad" uuid DEFAULT gen_random_uuid() NOT NULL,
  "tipo_especialidad" text,
  "fecha_creacion_especialidad" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "fecha_actualizacion_especialidad" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "fecha_eliminacion_especialidad" timestamp with time zone,
  PRIMARY KEY ("id_especialidad")
);

